import{_ as o,o as a,c as t,a0 as s}from"./chunks/framework.ChlVJx0I.js";const n="/pi-extensions/assets/tool-headers-before.02sES4CR.png",i="/pi-extensions/assets/tool-headers.C9wk17We.png",g=JSON.parse('{"title":"tool-headers extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/tool-headers.md","filePath":"extensions/tool-headers.md","lastUpdated":1792108345000}'),d={name:"extensions/tool-headers.md"};function r(h,e,l,c,p,w){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="tool-headers-extension" tabindex="-1">tool-headers extension <a class="header-anchor" href="#tool-headers-extension" aria-label="Permalink to &quot;tool-headers extension&quot;">​</a></h1><p>Every Tool row sits in the same colored block, and the block says nothing about which tool it holds. A <code>bash</code> and a <code>powershell</code> row print only <code>$ &lt;command&gt;</code>; a <code>codemode</code> row prints a JSON blob; a <code>bash</code> and a <code>bash_bg</code> row are identical in shape. This extension draws one line above each row&#39;s call line - the <strong>Tool row header</strong>: the tool name set in a rule - so the tool is told at a glance.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>The same session, once without the extension and once with it: the only difference is the header line above each call line.</p><table tabindex="0"><thead><tr><th>Without tool-headers</th><th>With tool-headers</th></tr></thead><tbody><tr><td><img src="'+n+'" alt="Tool rows without headers"></td><td><img src="'+i+`" alt="Tool rows with headers"></td></tr></tbody></table><h2 id="the-header-line" tabindex="-1">The header line <a class="header-anchor" href="#the-header-line" aria-label="Permalink to &quot;The header line&quot;">​</a></h2><p>The header is the fieldset legend of the row: the tool name in the theme&#39;s <code>toolTitle</code> (bold), set in a rule of <code>─</code> in <code>borderMuted</code>, running to the right edge of the box&#39;s content area. It is always exactly one line. When the width is tight, the rule shrinks to zero first (<code>── &lt;name&gt;</code>); only if the name alone no longer fits is the name truncated, ending in <code>…</code>. The name is the payload, so it truncates last.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(blank)</span></span>
<span class="line"><span>  ── read ──────────────────────────────────────────────────────────</span></span>
<span class="line"><span>  read src/auth/session.ts (1-40)</span></span>
<span class="line"><span>  42 lines</span></span>
<span class="line"><span>(blank)</span></span></code></pre></div><p>The header carries the tool name and nothing else: the call line below already carries the argument, and the row&#39;s background already carries the pending, success, and error states. The green box, its padding, and its state colors are untouched - the header is one line added above the call line, inside pi&#39;s own shell.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The header lands on every Tool row: the built-ins (<code>read</code>, <code>bash</code>, <code>powershell</code>, <code>edit</code>, <code>write</code>, <code>grep</code>, <code>find</code>, <code>ls</code>), this package&#39;s tools (<code>codegraph_*</code>, <code>bash_bg</code>, <code>job_wait</code>, <code>job_status</code>, <code>skill</code>, <code>codemode</code>), <code>tool_search</code>, and MCP tools. The rows that look alike today are exactly the ones that carry the value:</p><ul><li>A <code>bash</code> row and a <code>bash_bg</code> row are identical in shape; the header is what finally tells one from the other. The <code>bash_bg</code> call line stays <code>$ &lt;command&gt;</code> with no background marker (<a href="/pi-extensions/adr/0024-bash-bg-tool-row-shows-the-plain-command-line.html">ADR 0024</a>).</li><li>An MCP row&#39;s header shows <code>server/tool</code>, dropping pi&#39;s <code>mcp__</code> spelling, the same form the row&#39;s call line uses, so the two agree. Every other row shows the tool&#39;s raw name.</li><li>A tool that ships no renderer of its own keeps its stock call line (the shape pi&#39;s fallback draws) and gains the header above it.</li></ul><p>The <code>edit</code> row sets its own shell and draws its diff preview instead of the green box; its header goes above that preview, inside the self shell. Uniformity is the point: a row that skipped the header would be the row the operator misreads.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The mechanism is a <code>pi.registerToolRenderer()</code> resolver that calls <code>next()</code> first and wraps whatever pi or another extension would draw, prepending the header. Wrapping reaches built-in tools, this package&#39;s tools, and MCP tools through one path, and it composes with pi&#39;s own MCP resolver and with <code>bash_bg</code>&#39;s renderer instead of shadowing either (<a href="/pi-extensions/adr/0038-tool-row-headers-wrap-pi-tool-renderers.html">ADR 0038</a>). The resolver never registers a tool: it changes a picture, not an execution.</p><ul><li>A <code>next()</code> of <code>undefined</code> (a tool pi knows no renderer for) yields <code>undefined</code>, leaving the row exactly as pi draws it.</li><li>The wrapper keeps pi&#39;s inner component in per-row state and hands it back as <code>context.lastComponent</code>, so pi&#39;s built-in renderers keep their caches: the <code>edit</code> diff preview, the <code>write</code> highlight, the <code>bash</code> timer and truncation footer all still update, and click-to-expand and inline images keep working.</li><li>The renderer serves the interactive transcript and the HTML export alike; the header draws in both.</li></ul><h2 id="always-on" tabindex="-1">Always on <a class="header-anchor" href="#always-on" aria-label="Permalink to &quot;Always on&quot;">​</a></h2><p>The extension is always on, with no setting and no command. It is a rendering opinion in a personal package; the way to opt out is to not load the file.</p>`,18)])])}const u=o(d,[["render",r]]);export{g as __pageData,u as default};
